import base64,io,json,os,pathlib,shutil,subprocess,tarfile,datetime
old=pathlib.Path('/home/zbs/rf-round7-live-window-20261019');root=pathlib.Path('/home/zbs/rf-round7-live-window-20261019-attempt2');root.mkdir(exist_ok=False)
for f in ['deployment-original.json','configmap-original.json','backup-manifest.json','authorization.json']:shutil.copyfile(old/f,root/f)
(root/'build').mkdir();shutil.copyfile(old/'build/record.json',root/'build/record.json')
shutil.copytree(old/'lab',root/'lab',ignore=shutil.ignore_patterns('build','__pycache__'))
with tarfile.open(fileobj=io.BytesIO(base64.b64decode('')),mode='r:gz') as tf:
 for m in tf.getmembers():
  if not (root/'lab'/m.name).resolve().is_relative_to(root/'lab') or not m.isfile():raise RuntimeError('Unsafe archive')
 tf.extractall(root/'lab',filter='data')
env=os.environ.copy();env.update(GPU_LAB_APPROVED_LIVE_WINDOW='20261019',GPU_LAB_ROUND7_RUN_ROOT=str(root),KUBECONFIG=str(root/'nonexistent-offline-kubeconfig'))
# Regression on Linux before the original scheduler is stopped again.
cmd=['/home/zbs/rf-ablation-20261019-1425/lab/.venv/bin/python','-m','pytest','tests/test_round7_final_review.py','-q','--junitxml='+str(root/'pytest-fix-linux.xml')]
with (root/'pytest-fix-linux.log').open('w') as f:p=subprocess.run(cmd,cwd=root/'lab',env=env,stdout=f,stderr=subprocess.STDOUT)
if p.returncode:raise RuntimeError((root/'pytest-fix-linux.log').read_text())
with (root/'execution-console.log').open('w') as log:
 p=subprocess.Popen(['/home/zbs/rf-ablation-20261019-1425/lab/.venv/bin/python',str(root/'lab/scripts/round7_live_execute.py')],cwd=root,env=env,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
(root/'execution-pid.json').write_text(json.dumps(dict(pid=p.pid,started_utc=datetime.datetime.now(datetime.timezone.utc).isoformat())))
print(json.dumps(dict(pid=p.pid,root=str(root),linux_regression='14 passed',background=True)))
